def configure_providers_and_active_seasons(apps, schema_editor):
    Sport = apps.get_model("cfb", "Sport")
    Season = apps.get_model("cfb", "Season")
    db = schema_editor.connection.alias
    Sport.objects.using(db).filter(pk="college-football").update(data_provider="cfbd")
    Sport.objects.using(db).filter(pk="mens-college-basketball").update(data_provider="cbbd")
    # Preserve the formerly selected (newest) active season if legacy data has duplicates.
    for sport_id in Sport.objects.using(db).values_list("pk", flat=True):
        active = Season.objects.using(db).filter(sport_id=sport_id, is_active=True).order_by("-year", "-pk")
        selected = active.first()
        if selected:
            active.exclude(pk=selected.pk).update(is_active=False)


